function friendActionMarkup(username){const target=String(username||'').toLocaleLowerCase();const relationship=friendRows.find(f=>[f.requester,f.addressee].some(name=>String(name||'').toLocaleLowerCase()===target));if(relationship?.status==='accepted')return '<span class="profile-friend-state">✓ Amigos</span>';if(relationship?.status==='pending')return '<span class="profile-friend-state">Pedido pendente</span>';return '<button type="button" data-add-friend="'+escape(username)+'" aria-label="Enviar pedido para '+escape(username)+'">＋</button>'; }
async function refreshFriendBadge(receivedCount){
  const badge=document.querySelector('.friend-request-badge');
  if(!badge||!accountUser)return;
  try{
    let count=receivedCount;
    if(!Number.isFinite(Number(count))){
      const result=await chatApi('/api/chat/friends');
      count=result.counts?.received??(result.friends||[]).filter(friend=>friend.status==='pending'&&friend.addressee_id===accountUser.id).length;
    }
    count=Math.max(0,Number(count)||0);
    badge.textContent=count>99?'99+':String(count);
    badge.hidden=count===0;
  }catch{badge.hidden=true;}
}
