const escape = (value='') => String(value).replace(/[&<>"']/g, (char) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const safeUrl = (value='') => { try { const url = new URL(value); return ['https:','http:'].includes(url.protocol) ? url.href : '#'; } catch { return '#'; } };
const paragraphs = (value='') => escape(value).split(/\n+/).filter(Boolean).map(line => {const heading=line.match(/^(#{1,3})\s+(.+)$/);const text=(heading?heading[2]:line).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/~~(.+?)~~/g,'<del>$1</del>').replace(/__(.+?)__/g,'<u>$1</u>').replace(/`([^`]+)`/g,'<code>$1</code>');return heading?`<h${heading[1].length} class="formatted-heading">${text}</h${heading[1].length}>`:`<p>${text.replace(/(^|[^*])\*([^*]+)\*(?!\*)/g,'$1<em>$2</em>')}</p>`;}).join('');
