let noticeAudio=null,ringTimer=null,noticeAudioUnlocked=false;
function unlockNoticeAudio(){try{const AudioContextType=window.AudioContext||window.webkitAudioContext;if(!AudioContextType)return Promise.resolve(false);noticeAudio=noticeAudio||new AudioContextType();return (noticeAudio.state==='suspended'?noticeAudio.resume():Promise.resolve()).then(()=>{noticeAudioUnlocked=noticeAudio.state==='running';return noticeAudioUnlocked;}).catch(()=>false);}catch{return Promise.resolve(false);}}
document.addEventListener('pointerdown',()=>{void unlockNoticeAudio();},{once:true});document.addEventListener('keydown',()=>{void unlockNoticeAudio();},{once:true});
async function playNotice(kind='message'){try{const ctx=noticeAudio;if(!noticeAudioUnlocked||!ctx||ctx.state!=='running')return;const osc=ctx.createOscillator(),gain=ctx.createGain(),start=ctx.currentTime;osc.type='sine';osc.frequency.setValueAtTime(kind==='news'?880:kind==='friend'?740:kind==='call'?560:660,start);osc.frequency.setTargetAtTime(kind==='call'?690:kind==='news'?1040:880,start+.09,.035);gain.gain.setValueAtTime(.0001,start);gain.gain.exponentialRampToValueAtTime(kind==='call'?.22:.17,start+.025);gain.gain.exponentialRampToValueAtTime(.0001,start+.42);osc.connect(gain).connect(ctx.destination);osc.start(start);osc.stop(start+.44);}catch{}}
function ringStart(){ringStop();playNotice('call');ringTimer=setInterval(()=>playNotice('call'),1150);}
function ringStop(){clearInterval(ringTimer);ringTimer=null;}
function burstNotice(box){if(!box?.isConnected||box.classList.contains('bursting'))return;const rect=box.getBoundingClientRect(),particles=document.createElement('span');particles.className='notice-particles';particles.style.left=`${rect.left+rect.width/2}px`;particles.style.top=`${rect.top+rect.height/2}px`;for(let i=0;i<12;i++){const dot=document.createElement('i'),angle=(Math.PI*2*i)/12,distance=28+(i%3)*9;dot.style.setProperty('--px',`${Math.cos(angle)*distance}px`);dot.style.setProperty('--py',`${Math.sin(angle)*distance}px`);particles.append(dot);}document.body.append(particles);box.classList.remove('visible');box.classList.add('bursting');window.setTimeout(()=>{box.remove();particles.remove();},520);}
function showNotice(message){const previous=document.querySelector('.site-notice');if(previous){clearTimeout(previous._timer);previous.remove();}const box=document.createElement('div');box.className='site-notice';box.setAttribute('role','status');box.setAttribute('aria-live','polite');box.style.setProperty('--notice-duration','5.8s');const icon=document.createElement('span');icon.className='site-notice-icon';icon.setAttribute('aria-hidden','true');icon.textContent='✦';const copy=document.createElement('span');copy.className='site-notice-copy';copy.textContent=message;const close=document.createElement('button');close.className='site-notice-close';close.type='button';close.setAttribute('aria-label','Fechar notificação');close.textContent='×';const progress=document.createElement('span');progress.className='site-notice-progress';box.append(icon,copy,close,progress);document.body.append(box);requestAnimationFrame(()=>{if(box.isConnected)box.classList.add('visible');});close.addEventListener('click',()=>{clearTimeout(box._timer);burstNotice(box);});box._timer=window.setTimeout(()=>burstNotice(box),5800);}
function showIncomingCall(call){ringStart();document.querySelector('#incoming-call')?.remove();const dialog=document.createElement('div');if(!callsEnabled)return;dialog.id='incoming-call';dialog.className='incoming-call-backdrop';const avatar=call.profileImage?'<img src="'+escape(call.profileImage)+'" alt="Foto de '+escape(call.from)+'">':escape((call.from||'?').slice(0,1).toUpperCase());dialog.innerHTML='<section class="incoming-call-card"><span class="incoming-call-avatar">'+avatar+'<i aria-hidden="true">☎</i></span><small>CHAMADA RECEBIDA · '+(call.kind==='video'?'VÍDEO':'ÁUDIO')+'</small><h2>'+escape(call.from)+'</h2><p>está chamando você</p><div><button class="button button-gold" data-call-answer>Atender</button><button class="button button-outline" data-call-reject>Recusar</button></div></section>';document.body.append(dialog);dialog.querySelector('[data-call-answer]').addEventListener('click',()=>{ringStop();dialog.remove();answerCall(call);});dialog.querySelector('[data-call-reject]').addEventListener('click',()=>{ringStop();dialog.remove();chatApi('/api/chat/calls/'+encodeURIComponent(call.id)+'/signals',{method:'POST',body:JSON.stringify({type:'end'})}).catch(()=>{});incomingCall=null;});}
function ensureAccountEvents(){if(!accountUser||chatStream)return;chatStream=new EventSource('/api/chat/events');chatStream.addEventListener('message',e=>{const m=JSON.parse(e.data);if(m.conversationId===chatActive&&document.querySelector('#chat-messages'))loadMessages(chatActive);if(m.senderId!==accountUser.id&&accountUser.presenceStatus!=='dnd'){playNotice('message');showNotice('Nova mensagem de '+m.username);}});chatStream.addEventListener('message-deleted',e=>{const m=JSON.parse(e.data);if(m.conversationId===chatActive&&document.querySelector('#chat-messages'))loadMessages(chatActive);});chatStream.addEventListener('friend-request',e=>{const x=JSON.parse(e.data);if(accountUser.presenceStatus!=='dnd'){playNotice('friend');showNotice('Novo pedido de amizade de '+x.username);}refreshFriendBadge();if(document.querySelector('#conversation-list'))loadChat();});chatStream.addEventListener('friend-accepted',()=>{if(accountUser.presenceStatus!=='dnd'){playNotice('friend');showNotice('Pedido de amizade aceito.');}refreshFriendBadge();if(document.querySelector('#conversation-list'))loadChat();});chatStream.addEventListener('friend-rejected',e=>{const x=JSON.parse(e.data);if(accountUser.presenceStatus!=='dnd'){playNotice('friend');showNotice(x.username+' recusou o pedido de amizade.');}refreshFriendBadge();if(document.querySelector('#conversation-list'))loadChat();});chatStream.addEventListener('friend-cancelled',()=>{refreshFriendBadge();if(document.querySelector('#conversation-list'))loadChat();});chatStream.addEventListener('friend-removed',e=>{const x=JSON.parse(e.data);if(accountUser.presenceStatus!=='dnd')showNotice(x.username+' desfez a amizade.');loadChat();});chatStream.addEventListener('roles-updated',async()=>{try{const r=await fetch('/api/user/me');if(r.ok){accountUser=await r.json();accountCsrf=accountUser.csrfToken;showNotice('Seus cargos foram atualizados.');render();}}catch{}});chatStream.addEventListener('banned',e=>{chatStream?.close();chatStream=null;accountUser=null;accountCsrf='';accountMode='login';accountFeedback='Sua conta foi suspensa.';showNotice('Acesso suspenso pela equipe.');location.hash='#conta';render();});chatStream.addEventListener('group-created',e=>{const x=JSON.parse(e.data);if(accountUser.presenceStatus!=='dnd'){playNotice('message');showNotice('Você foi adicionado ao grupo '+x.name);}loadChat();});chatStream.addEventListener('group-updated',e=>{const x=JSON.parse(e.data);if(x.id===chatActive)loadMessages(chatActive);loadChat();});chatStream.addEventListener('group-deleted',e=>{const x=JSON.parse(e.data);if(x.id===chatActive){chatActive='';try{sessionStorage.removeItem('frontline-chat-active');}catch{}}loadChat();});chatStream.addEventListener('news',e=>{const x=JSON.parse(e.data);playNotice('news');showNotice('Nova notícia: '+x.title);});chatStream.addEventListener('incoming-call',e=>{if(!callsEnabled||accountUser.presenceStatus==='dnd')return;incomingCall=JSON.parse(e.data);showIncomingCall(incomingCall);});chatStream.addEventListener('call-rejoin',e=>{if(!callsEnabled||accountUser.presenceStatus==='dnd')return;const call=JSON.parse(e.data);void rejoinCall(call,true);});chatStream.addEventListener('community-request-deleted',()=>{if(location.hash==='#pedidos')loadCommunityRequests();});chatStream.addEventListener('community-request',e=>{const x=JSON.parse(e.data);playNotice('news');showNotice('Novo pedido de '+x.by+': '+x.title);if(location.hash==='#pedidos')loadCommunityRequests();});chatStream.addEventListener('community-comment',e=>{if(location.hash==='#pedidos'){playNotice('message');loadCommunityRequests();}});chatStream.addEventListener('community-decision',e=>{if(location.hash==='#pedidos'){const x=JSON.parse(e.data);showNotice(x.status==='approved'?'Um pedido foi aprovado pela ONU.':'Um pedido foi recusado pela ONU.');loadCommunityRequests();}});chatStream.addEventListener('call-timeout',e=>{const call=JSON.parse(e.data);if(incomingCall?.id===call.id){ringStop();document.querySelector('#incoming-call')?.remove();incomingCall=null;showNotice('A chamada expirou após 60 segundos sem resposta.');}if(activeCall===call.id){void stopCall(false);showNotice('A chamada foi encerrada: ninguém atendeu em 60 segundos.');}});chatStream.addEventListener('call-signal',()=>{if(callsEnabled)pollCallSignals();});}
async function refreshPublishedContent(){if(siteRefreshBusy){siteRefreshQueued=true;return;}siteRefreshBusy=true;do{siteRefreshQueued=false;try{const response=await fetch('/api/public',{cache:'no-store'});if(!response.ok)continue;data=await response.json();const route=(location.hash.slice(1)||'inicio').toLowerCase();if(!['chat','conta','carrinho'].includes(route)&&!route.startsWith('perfil/')){const scrollY=window.scrollY;render();window.scrollTo({top:scrollY,behavior:'auto'});}}catch(error){console.warn('Não foi possível atualizar o conteúdo ao vivo:',error);}}while(siteRefreshQueued);siteRefreshBusy=false;}
function ensureSiteContentEvents(){if(siteContentStream)return;siteContentStream=new EventSource('/api/site/events');siteContentStream.addEventListener('ready',()=>{if(siteStreamConnected)void refreshPublishedContent();siteStreamConnected=true;});siteContentStream.addEventListener('content-updated',()=>{void refreshPublishedContent();});siteContentStream.addEventListener('error',()=>{if(siteContentStream?.readyState===EventSource.CLOSED){siteContentStream=null;}});if(!window.__frontlineSitePoll){window.__frontlineSitePoll=window.setInterval(()=>{if(document.visibilityState==='visible')void refreshPublishedContent();},30000);}}
