function renderNow() {
  if(!data)return;
  const rawRoute=location.hash.slice(1)||'inicio',profileMatch=rawRoute.match(/^perfil\/(.+)$/i),route=profileMatch?'perfil':rawRoute.toLowerCase();
  const selected=labels[route]?route:'inicio';
  document.body.classList.toggle('chat-mode',selected==='chat'&&Boolean(accountUser));
  if(currentRoute!==selected){if(currentRoute!==null)window.scrollTo(0,0);currentRoute=selected;}
  if(!location.hash) history.replaceState(null,'','#inicio');
  document.title=`${labels[selected]} · ${data.settings.server.name||'Frontline MC'}`;
  main.innerHTML=renderPage(selected);restorePageDraft();
  nav.querySelectorAll('[data-member-route]').forEach(link=>link.remove());if(accountUser){for(const [route,label] of [['mapa','Mapa'],['pedidos','Pedidos']]){const link=document.createElement('a');link.href='#'+route;link.dataset.route=route;link.dataset.memberRoute='true';link.textContent=label;nav.append(link);}}
  nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.dataset.route===selected));
  const accountLink=document.querySelector('.account-cta');
  const accountLabel=document.querySelector('#account-label');const accountIcon=document.querySelector('.account-icon');if(accountIcon){accountIcon.innerHTML=accountUser?'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.5"></circle><path d="M4.8 20c.8-3.5 3.3-5.3 7.2-5.3s6.4 1.8 7.2 5.3"></path></svg>':'◉';accountIcon.classList.remove('has-avatar');accountIcon.hidden=false;}const panelRoles=accountUser?.roles||[accountUser?.role,accountUser?.secondaryRole].filter(Boolean);const panelLink=document.querySelector('.panel-cta');panelLink.hidden=!(accountUser&&panelRoles.some(r=>['adm','owner','creator','funder'].includes(r)));let chatLink=document.querySelector('.chat-cta');if(accountUser&&!chatLink){chatLink=document.createElement('a');chatLink.className='header-cta chat-cta';chatLink.href='#chat';chatLink.dataset.route='chat';chatLink.innerHTML='<span class="chat-header-avatar">'+(accountUser.profileImage?'<img src="'+escape(accountUser.profileImage)+'" alt="">':escape(accountUser.username.slice(0,1).toUpperCase()))+'</span><span class="chat-header-copy"><strong>Amigos</strong><small>'+escape(accountUser.username)+'</small></span><b class="friend-request-badge" hidden>0</b>'; document.querySelector('.header-actions').prepend(chatLink);}if(!accountUser)chatLink?.remove();else{chatLink.innerHTML='<span class="chat-header-avatar">'+(accountUser.profileImage?'<img src="'+escape(accountUser.profileImage)+'" alt="">':escape(accountUser.username.slice(0,1).toUpperCase()))+'</span><span class="chat-header-copy"><strong>Amigos</strong><small>'+escape(accountUser.username)+'</small></span><b class="friend-request-badge" hidden>0</b>';refreshFriendBadge();}
  accountLink.classList.toggle('active',selected==='conta');
  accountLabel.textContent=accountUser?'Conta':'Entrar';if(accountIcon)accountIcon.hidden=false;
  accountLink.setAttribute('aria-label',accountUser?`Minha conta: ${accountUser.username}`:'Entrar ou criar conta');
  toggle.setAttribute('aria-expanded','false');nav.classList.remove('open');
  clearInterval(statusTimer);
  if(selected==='inicio') { refreshStatus(); statusTimer=setInterval(refreshStatus,30000); }if(selected==='conta'&&accountUser)loadAccountOrders();if(selected==='chat'&&accountUser){void loadChat().then(()=>restoreActiveCall()).catch(error=>console.warn('Falha ao restaurar conversas/chamada:',error));}if(selected==='pedidos'&&accountUser){loadCommunityRequests();}if(selected==='perfil'&&profileMatch)loadPublicProfile(decodeURIComponent(profileMatch[1]));if(accountUser)ensureAccountEvents();else if(chatStream){chatStream.close();chatStream=null;}
}
function render() {
  if(!data)return;
  if(document.startViewTransition&&!matchMedia('(prefers-reduced-motion: reduce)').matches) {
    document.startViewTransition(()=>renderNow());
    return;
  }
  renderNow();
  main.classList.remove('page-enter');
  void main.offsetWidth;
  main.classList.add('page-enter');
}
