function syncCustomSettingsSelect(select){if(!select)return;let wrap=select.closest('.settings-select-wrap');if(!wrap){wrap=document.createElement('div');wrap.className='settings-select-wrap';select.parentNode.insertBefore(wrap,select);wrap.append(select);select.classList.add('settings-select-native');const trigger=document.createElement('button');trigger.type='button';trigger.className='settings-select-trigger';trigger.dataset.customSelectToggle='';trigger.setAttribute('aria-haspopup','listbox');trigger.setAttribute('aria-expanded','false');wrap.append(trigger);const list=document.createElement('div');list.className='settings-select-options';list.hidden=true;list.id=select.id+'-options';list.setAttribute('role','listbox');wrap.append(list);trigger.setAttribute('aria-controls',list.id);select.addEventListener('change',()=>syncCustomSettingsSelect(select));}const trigger=wrap.querySelector('.settings-select-trigger'),list=wrap.querySelector('.settings-select-options');if(!trigger||!list)return;const selected=select.selectedOptions[0];trigger.innerHTML='<span>'+escape(selected?.textContent||'Selecione uma opção')+'</span><i aria-hidden="true">⌄</i>';list.innerHTML=[...select.options].map(option=>'<button type="button" role="option" data-custom-select-value="'+escape(option.value)+'" aria-selected="'+(option.selected?'true':'false')+'" '+(option.disabled?'disabled':'')+'>'+escape(option.textContent)+'</button>').join('');}
