async function loadSettingsAudioDevices(){const input=document.querySelector('#settings-audio-input'),output=document.querySelector('#settings-audio-output'),status=document.querySelector('#settings-audio-status');if(!input||!output||!navigator.mediaDevices?.enumerateDevices){if(status)status.textContent='Este navegador não oferece seleção de dispositivos de áudio.';return;}let permissionStream=null;try{if(status)status.textContent='Detectando dispositivos…';try{permissionStream=await navigator.mediaDevices.getUserMedia({audio:true});}catch{}const devices=await navigator.mediaDevices.enumerateDevices(),inputs=devices.filter(device=>device.kind==='audioinput'),outputs=devices.filter(device=>device.kind==='audiooutput');input.innerHTML='<option value="">Microfone padrão do PC</option>'+inputs.map((device,index)=>'<option value="'+escape(device.deviceId)+'">'+escape(device.label||('Microfone '+(index+1)))+'</option>').join('');input.value=inputs.some(device=>device.deviceId===selectedMicId)?selectedMicId:'';output.innerHTML='<option value="">Saída padrão do PC</option>'+outputs.map((device,index)=>'<option value="'+escape(device.deviceId)+'">'+escape(device.label||('Saída de áudio '+(index+1)))+'</option>').join('');output.value=outputs.some(device=>device.deviceId===selectedOutputId)?selectedOutputId:'';if(status)status.textContent=inputs.length+' microfone(s) e '+outputs.length+' saída(s) encontrados. A lista de telas aparece ao usar “Escolher tela”.';}catch(error){if(status)status.textContent=error.name==='NotAllowedError'?'Permita o acesso ao microfone nas configurações do navegador.':error.message;}finally{permissionStream?.getTracks().forEach(track=>track.stop());}}
 async function testSettingsMicrophone(button){const status=document.querySelector('#settings-audio-status'),monitor=document.querySelector('#settings-mic-monitor'),meter=document.querySelector('#settings-mic-meter');if(micTestStream){if(micTestStream!==localMedia)micTestStream.getTracks().forEach(track=>track.stop());if(micTestContext)await micTestContext.close().catch(()=>{});micTestStream=null;micTestContext=null;if(monitor)monitor.srcObject=null;button.textContent='Testar microfone';meter?.style.setProperty('--level','0%');if(status)status.textContent='Teste de microfone encerrado.';return;}try{micTestStream=await navigator.mediaDevices.getUserMedia({audio:microphoneConstraints()});if(monitor){monitor.srcObject=micTestStream;monitor.muted=false;monitor.volume=.55;if(selectedOutputId&&monitor.setSinkId)await monitor.setSinkId(selectedOutputId);await monitor.play();}const Ctx=window.AudioContext||window.webkitAudioContext;if(Ctx){micTestContext=new Ctx();await micTestContext.resume();const analyser=micTestContext.createAnalyser(),source=micTestContext.createMediaStreamSource(micTestStream);analyser.fftSize=256;source.connect(analyser);const samples=new Uint8Array(analyser.frequencyBinCount),draw=()=>{if(!micTestContext)return;analyser.getByteTimeDomainData(samples);let sum=0;for(const value of samples){const delta=(value-128)/128;sum+=delta*delta;}meter?.style.setProperty('--level',Math.min(100,Math.round(Math.sqrt(sum/samples.length)*260))+'%');micTestFrame=requestAnimationFrame(draw);};draw();}button.textContent='Parar teste';if(status)status.textContent='Microfone ativo. Fale para conferir o retorno e o medidor. Use fones para evitar eco.';}catch(error){if(micTestStream&&micTestStream!==localMedia)micTestStream.getTracks().forEach(track=>track.stop());micTestStream=null;if(status)status.textContent=error.name==='NotAllowedError'?'Permita o microfone nas configurações do navegador.':error.message;showNotice('Não foi possível testar o microfone: '+error.message);}}
async function testSettingsOutput(){const status=document.querySelector('#settings-audio-status');try{const Ctx=window.AudioContext||window.webkitAudioContext;if(!Ctx)throw new Error('Seu navegador não oferece teste de áudio.');settingsOutputAudio?.pause();settingsOutputAudio=null;const context=new Ctx(),destination=context.createMediaStreamDestination(),osc=context.createOscillator(),gain=context.createGain(),audio=new Audio();audio.srcObject=destination.stream;audio.volume=.22;if(selectedOutputId&&audio.setSinkId)await audio.setSinkId(selectedOutputId);osc.type='sine';osc.frequency.value=660;gain.gain.value=.16;osc.connect(gain).connect(destination);await context.resume();await audio.play();osc.start();osc.stop(context.currentTime+.35);settingsOutputAudio=audio;if(status)status.textContent='Tom de teste enviado para a saída selecionada.';setTimeout(()=>{audio.pause();audio.srcObject=null;context.close().catch(()=>{});},600);}catch(error){if(status)status.textContent=error.message;showNotice('Não foi possível testar a saída: '+error.message);}}
 async function selectSettingsScreen(){if(!navigator.mediaDevices?.getDisplayMedia){showNotice('Este navegador não oferece captura de tela.');return;}try{stopSettingsScreen();const height=Number(videoQuality),width=Math.round(height*16/9);settingsScreenStream=await navigator.mediaDevices.getDisplayMedia({video:{width:{ideal:width},height:{ideal:height},frameRate:{ideal:30,max:60}},audio:false});const video=document.querySelector('#settings-screen-preview');if(video){video.srcObject=settingsScreenStream;await video.play().catch(()=>{});}document.querySelector('[data-settings-screen-empty]')?.setAttribute('hidden','');document.querySelector('[data-action="settings-stop-screen"]')?.removeAttribute('hidden');const status=document.querySelector('#settings-video-status');if(status)status.textContent='Prévia ativa · resolução solicitada: '+height+'p. A resolução final depende da tela e do navegador.';settingsScreenStream.getVideoTracks()[0].addEventListener('ended',stopSettingsScreen,{once:true});}catch(error){if(error.name!=='NotAllowedError')showNotice('Não foi possível selecionar essa tela: '+error.message);}}
