async function flushPendingIce(){if(!peerCall?.remoteDescription)return;for(const candidate of pendingIceCandidates.splice(0)){try{await peerCall.addIceCandidate(candidate);}catch(error){console.warn('ICE candidate ignorado:',error);}}}
function revealAvatarAfterVideoFrame(video,avatar){if(!video)return;const reveal=()=>{if(video.readyState>=HTMLMediaElement.HAVE_CURRENT_DATA&&video.videoWidth>0&&video.videoHeight>0){video.classList.add('has-frame');avatar?.classList.add('has-video');}};video.addEventListener('loadeddata',reveal,{once:true});video.addEventListener('playing',reveal,{once:true});requestAnimationFrame(reveal);}
