function callIcon(name){const paths={expand:'<path d="M8 3H5a2 2 0 0 0-2 2v3m13-5h3a2 2 0 0 1 2 2v3M3 16v3a2 2 0 0 0 2 2h3m13-5v3a2 2 0 0 1-2 2h-3"/><path d="M8 8 3 3m13 5 5-5M8 16l-5 5m13-5 5 5"/>',mic:'<path d="M12 18a4 4 0 0 0 4-4V7a4 4 0 0 0-8 0v7a4 4 0 0 0 4 4Z"/><path d="M19 11v3a7 7 0 0 1-14 0v-3M12 21v-3m-4 6h8"/>',micMuted:'<path d="M12 18a4 4 0 0 0 4-4V7a4 4 0 0 0-8 0v7a4 4 0 0 0 4 4Z"/><path d="M19 11v3a7 7 0 0 1-11.8 5M12 21v-3m-4 6h8M3 3l18 18"/>',headsetMuted:'<path d="M3 13v-1a9 9 0 0 1 18 0v1"/><rect x="2.5" y="12" width="5" height="8" rx="2"/><rect x="16.5" y="12" width="5" height="8" rx="2"/><path d="M21.5 18a4 4 0 0 1-4 4H14M3 3l18 18"/>',headset:'<path d="M3 13v-1a9 9 0 0 1 18 0v1"/><rect x="2.5" y="12" width="5" height="8" rx="2"/><rect x="16.5" y="12" width="5" height="8" rx="2"/><path d="M21.5 18a4 4 0 0 1-4 4H14"/>',camera:'<rect x="3" y="6" width="13" height="12" rx="2"/><path d="m16 10 5-3v10l-5-3"/>',cameraOff:'<rect x="3" y="6" width="13" height="12" rx="2"/><path d="m16 10 5-3v10l-5-3M3 3l18 18"/>',monitor:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4m-5-9 3-3 2 2 3-4"/>',stopShare:'<rect x="3" y="4" width="18" height="13" rx="2"/><path d="M8 21h8m-4-4v4M3 3l18 18"/>',end:'<path d="M4 15a12 12 0 0 1 16 0l-2 4-4-2v-2a5 5 0 0 0-4 0v2l-4 2-2-4Z"/>'};return '<svg viewBox="0 0 24 24" aria-hidden="true">'+(paths[name]||paths.mic)+'</svg>';}
function updateCallToggleButtons(){document.querySelectorAll('[data-action="call-mic-toggle"]').forEach(button=>{button.innerHTML=callIcon(microphoneMuted||outputMuted?'micMuted':'mic');button.setAttribute('aria-label',microphoneMuted||outputMuted?'Ativar microfone':'Silenciar microfone');button.title=microphoneMuted||outputMuted?'Ativar microfone':'Silenciar microfone';button.setAttribute('aria-pressed',String(microphoneMuted||outputMuted));button.classList.toggle('is-muted',microphoneMuted||outputMuted);});document.querySelectorAll('[data-action="call-output-toggle"]').forEach(button=>{button.innerHTML=callIcon(outputMuted?'headsetMuted':'headset');button.setAttribute('aria-label',outputMuted?'Reativar headset e microfone':'Silenciar headset e microfone');button.title=outputMuted?'Reativar headset e microfone':'Silenciar headset e microfone';button.setAttribute('aria-pressed',String(outputMuted));button.classList.toggle('is-muted',outputMuted);});const localAvatar=document.querySelector('#local-call-avatar'),micBadge=localAvatar?.querySelector('[data-mic-muted]'),headsetBadge=localAvatar?.querySelector('[data-headset-muted]');if(micBadge)micBadge.hidden=!(microphoneMuted||outputMuted);if(headsetBadge)headsetBadge.hidden=!outputMuted;}
