function notificationIcon(kind){const paths={news:'M5 4h14v16H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2Zm3 4h8M8 11h8M8 14h5',friend:'M16 20v-1.5a3.5 3.5 0 0 0-3.5-3.5h-5A3.5 3.5 0 0 0 4 18.5V20m6-9a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7Zm8-3v6m-3-3h6',message:'M4 5h16v12H9l-5 3V5Zm4 4h8m-8 4h6',nation:'M4 20V5l8 3 8-3v15l-8-3-8 3Zm8-12v12',diplomacy:'M12 3v18m-7-15h14M5 6l-3 6h6L5 6Zm14 0-3 6h6l-3-6ZM8 21h8',order:'M6 4h12v16H6zM9 8h6m-6 4h6m-6 4h4'};return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[kind]||'M12 3v18m-9-9h18M5.6 5.6l12.8 12.8m0-12.8L5.6 18.4'}"/></svg>`;}
