function notificationMarkup(){const items=siteNotifications.length?siteNotifications.map((item,index)=>`<article class="notification-item kind-${['news','friend','message','nation','diplomacy','order'].includes(item.kind)?item.kind:'general'}" style="--notification-index:${Math.min(index,8)}"><a href="${escape(item.href||'#inicio')}" data-notification-open><span class="notification-kind">${notificationIcon(item.kind)}</span><span class="notification-copy"><span class="notification-meta"><small>${notificationKindLabel(item.kind)}</small><time datetime="${escape(item.createdAt||'')}" data-relative-time="${escape(item.createdAt||'')}">${escape(relativeAge(item.createdAt)||'Agora há pouco')}</time></span><strong>${escape(item.title)}</strong><span class="notification-body">${escape(item.body)}</span></span></a><button type="button" data-notification-dismiss="${item.id}" aria-label="Dispensar notificação">×</button></article>`).join(''):'<div class="notification-empty"><span>✦</span><strong>Tudo em dia</strong><small>Novas notificações aparecerão aqui.</small></div>';return `<section class="notification-popover" ${notificationPanelOpen?'':'hidden'} aria-label="Notificações"><header><div><span class="notification-header-kicker"><i></i> CENTRAL FRONTLINE</span><h2>Notificações <b>${siteNotifications.length}</b></h2><p>Novidades e atividade recente da comunidade</p></div><button type="button" data-notification-close aria-label="Fechar notificações">×</button></header><div class="notification-list">${items}</div><footer><span>Atualizações da sua comunidade</span><span>Dispense as que já conferiu com <b>×</b></span></footer></section>`;}
function syncNotificationBell(){const actions=document.querySelector('.header-actions');if(!actions)return;let button=actions.querySelector('[data-notification-bell]');if(!accountUser){button?.remove();actions.querySelector('.notification-popover')?.remove();return;}if(!button){button=document.createElement('button');button.type='button';button.className='header-cta notification-bell';button.dataset.notificationBell='';button.setAttribute('aria-label','Notificações');button.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg><b></b>';actions.insertBefore(button,actions.firstChild);}button.querySelector('b').textContent=siteNotifications.length>99?'99+':String(siteNotifications.length);button.classList.toggle('has-notifications',siteNotifications.length>0);button.setAttribute('aria-expanded',String(notificationPanelOpen));let popover=actions.querySelector('.notification-popover');if(!popover){popover=document.createElement('div');actions.append(popover);}popover.outerHTML=notificationMarkup();}
async function loadNotifications(){if(!accountUser)return;try{const response=await fetch('/api/user/notifications',{cache:'no-store'}),result=await response.json();if(response.ok){siteNotifications=result.notifications||[];syncNotificationBell();}}catch{}}
function ensureNotificationEvents(){if(!accountUser)return;if(notificationStream)notificationStream.close();notificationStream=new EventSource('/api/chat/events');notificationStream.addEventListener('notification-created',event=>{const item=JSON.parse(event.data);if(!siteNotifications.some(existing=>existing.id===item.id))siteNotifications.unshift(item);syncNotificationBell();const quiet=accountUser?.presenceStatus==='dnd'&&['message','friend'].includes(item.kind);if(!quiet){playNotice(item.kind==='friend'?'friend':'news');showNotice(item.title);}});}
const renderNowWithNotifications=renderNow;renderNow=function(){renderNowWithNotifications();if(accountUser&&notificationLoadedFor!==Number(accountUser.id)){notificationLoadedFor=Number(accountUser.id);void loadNotifications();ensureNotificationEvents();}syncNotificationBell();};
window.setInterval(()=>document.querySelectorAll('[data-relative-time]').forEach(node=>{const stamp=Number(node.dataset.relativeTime),badge=node.closest('.news-new-badge');if(badge&&Number.isFinite(stamp)&&Date.now()-stamp>=72*60*60*1000){badge.closest('.news-card-link')?.classList.remove('is-new');badge.remove();return;}const label=relativeAge(node.dataset.relativeTime);if(label)node.textContent=label;}),60000);
const submitCommunityRequestOriginal=submitCommunityRequest;submitCommunityRequest=async function(form){if(form.elements.type.value!=='nation')return submitCommunityRequestOriginal(form);const button=form.querySelector('[type="submit"]'),errorNode=form.querySelector('.diplomacy-form-error');button.disabled=true;if(errorNode)errorNode.textContent='';try{const file=form.querySelector('[name="nationImage"]').files[0];if(!file)throw new Error('Adicione a imagem da nação.');if(file.size>8*1024*1024)throw new Error('A imagem pode ter até 8 MB.');const image=await communityUpload(file),values=new FormData(form);const response=await fetch('/api/nation-applications',{method:'POST',headers:{'Content-Type':'application/json','x-csrf-token':accountCsrf},body:JSON.stringify({nationName:values.get('nationName'),leaderName:values.get('leaderName'),description:values.get('nationDescription'),rules:values.get('nationRules'),image})}),result=await response.json();if(!response.ok)throw new Error(result.error||'Não foi possível enviar o pedido.');form.reset();form.querySelector('[data-nation-image-name]').textContent='Nenhuma imagem selecionada';showNotice('Pedido de criação enviado à ONU.');await loadNotifications();}catch(error){if(errorNode)errorNode.textContent=error.message;else showNotice(error.message);}finally{if(button.isConnected)button.disabled=false;}};
function renderCommunityRequests(){const html=renderCommunityRequestsLegacy();const replacement=`<form id="community-request-form" class="diplomacy-compose diplomacy-compose-unified"><span class="system-kicker">NOVO PEDIDO</span><h2>Apresente sua proposta</h2><label class="diplomacy-type-field">Tipo de pedido<input type="hidden" name="type" value="meeting"><details class="diplomacy-select"><summary><span data-diplomacy-type-label>Solicitar reunião</span><svg viewBox="0 0 16 16" aria-hidden="true"><path d="m3.5 6 4.5 4 4.5-4"/></svg></summary><div class="diplomacy-select-options" role="listbox" aria-label="Tipo de pedido"><button type="button" role="option" data-request-type="meeting" aria-selected="true"><span>Solicitar reunião</span><small>Peça uma conversa diplomática</small><i>✓</i></button><button type="button" role="option" data-request-type="war" aria-selected="false"><span>Declarar guerra</span><small>Envie uma declaração para análise da ONU</small><i></i></button><button type="button" role="option" data-request-type="nation" aria-selected="false"><span>Criar nação</span><small>Envie nome, regras, liderança, descrição e imagem para aprovação</small><i></i></button></div></details></label><div data-standard-request><label>Título<input name="title" maxlength="120" required placeholder="Ex.: Reunião sobre a fronteira norte"></label><label>Descrição<textarea name="body" maxlength="12000" required placeholder="Explique os motivos, os envolvidos e o que você solicita."></textarea></label><div class="diplomacy-upload-area"><label class="diplomacy-upload"><span class="diplomacy-upload-icon">＋</span><span class="diplomacy-upload-copy"><strong>Adicionar imagens</strong><small>PNG, JPG ou WebP · até 5 imagens</small></span><span class="diplomacy-upload-count" data-upload-count>Nenhuma imagem</span><input class="diplomacy-file-input" type="file" name="images" accept="image/png,image/jpeg,image/webp" multiple></label><div class="diplomacy-upload-previews" data-upload-previews></div></div></div><div class="nation-application-fields" data-nation-fields hidden><div class="form-grid"><label>Nome da nação<input name="nationName" maxlength="100" placeholder="Ex.: República de Aurora"></label><label>Nome do líder<input name="leaderName" maxlength="80" placeholder="Nome do líder da nação"></label><label class="full">Descrição breve<textarea name="nationDescription" maxlength="3000" placeholder="Apresente a história e os objetivos da nação."></textarea></label><label class="full">Regras da nação<textarea name="nationRules" maxlength="6000" placeholder="Descreva as regras e princípios da nação."></textarea></label></div><label class="nation-image-upload"><input type="file" name="nationImage" accept="image/png,image/jpeg,image/webp" hidden><span class="nation-image-icon" aria-hidden="true">＋</span><span class="nation-image-copy"><strong>Imagem da nação</strong><small data-nation-image-name>PNG, JPG ou WebP · máximo 8 MB</small></span><span class="nation-image-action">Escolher imagem</span></label></div><p class="diplomacy-form-error" role="alert">${escape(communityData.error||'')}</p><button class="button button-gold" type="submit">Enviar para análise <span>→</span></button></form>`;return html.replace(/<form id="community-request-form"[\s\S]*?<\/form>/,replacement);}
main.addEventListener('click',event=>{const option=event.target.closest('[data-request-type="nation"], [data-request-type="meeting"], [data-request-type="war"]');if(option){const form=option.closest('#community-request-form');if(!form)return;const nation=option.dataset.requestType==='nation',standard=form.querySelector('[data-standard-request]'),nationFields=form.querySelector('[data-nation-fields]');if(standard)standard.hidden=nation;if(nationFields)nationFields.hidden=!nation;for(const name of ['title','body']){const field=form.elements.namedItem(name);if(field)field.required=!nation;}for(const name of ['nationName','leaderName','nationDescription','nationRules']){const field=form.elements.namedItem(name);if(field)field.required=nation;}}});
main.addEventListener('change',event=>{const input=event.target.closest('[name="nationImage"]');if(input){const label=input.closest('.nation-image-upload')?.querySelector('[data-nation-image-name]');if(label)label.textContent=input.files[0]?.name||'Nenhuma imagem selecionada';}});
document.addEventListener('click',event=>{const dismiss=event.target.closest('[data-notification-dismiss]');if(dismiss){event.preventDefault();event.stopPropagation();const id=Number(dismiss.dataset.notificationDismiss);fetch('/api/user/notifications/'+id,{method:'DELETE',headers:{'x-csrf-token':accountCsrf}}).then(async response=>{if(!response.ok)throw new Error('Não foi possível remover esta notificação.');siteNotifications=siteNotifications.filter(item=>item.id!==id);syncNotificationBell();}).catch(error=>showNotice(error.message));return;}if(event.target.closest('[data-notification-close]')){notificationPanelOpen=false;syncNotificationBell();return;}if(event.target.closest('[data-notification-bell]')){event.preventDefault();notificationPanelOpen=!notificationPanelOpen;syncNotificationBell();return;}if(event.target.closest('[data-notification-open]')){notificationPanelOpen=false;syncNotificationBell();return;}if(notificationPanelOpen&&!event.target.closest('.notification-bell')&&!event.target.closest('.notification-popover')){notificationPanelOpen=false;syncNotificationBell();}});
document.querySelector('#year').textContent=new Date().getFullYear();
main.addEventListener('input',e=>{const card=e.target.closest('[data-news-id]');if(card){const b=card.querySelector('[data-action="save-news"]');if(b)b.disabled=true;previewed?.delete(card.dataset.key);}});
main.addEventListener('change',async e=>{const chatFiles=e.target.closest('[data-chat-images]');if(chatFiles){try{for(const file of [...chatFiles.files].slice(0,5-pendingChatImages.length)){if(file.size>5*1024*1024)throw new Error('Cada imagem pode ter até 5 MB.');const r=await fetch('/api/user/chat-upload',{method:'POST',headers:{'Content-Type':'application/octet-stream','x-csrf-token':accountCsrf},body:await file.arrayBuffer()});const d=await r.json();if(!r.ok)throw new Error(d.error);pendingChatImages.push(d.url);}chatFiles.value='';const preview=document.querySelector('#chat-attachment-preview');if(preview)preview.innerHTML=pendingChatImages.map((url,i)=>'<div><img src="'+escape(url)+'"><button type="button" data-remove-chat-image="'+i+'">×</button></div>').join('');}catch(err){alert(err.message);}return;}const file=e.target.closest('[data-profile-upload]');if(!file||!file.files[0]||!accountCsrf)return;try{if(file.files[0].size>5*1024*1024)throw new Error('A foto pode ter até 5 MB.');const r=await fetch('/api/user/upload',{method:'POST',headers:{'Content-Type':'application/octet-stream','x-csrf-token':accountCsrf},body:await file.files[0].arrayBuffer()});const d=await r.json();if(!r.ok)throw new Error(d.error);accountUser.profileImage=d.url;render();}catch(err){accountFeedback=err.message;render();}});load();

main.addEventListener("change",event=>{const input=event.target.closest(".nation-image-upload input[type=file]");if(!input)return;const label=input.closest(".nation-image-upload"),file=input.files?.[0],copy=label.querySelector(".nation-image-copy"),icon=label.querySelector(".nation-image-icon");let preview=label.querySelector("[data-nation-image-preview]");if(input.dataset.previewUrl){URL.revokeObjectURL(input.dataset.previewUrl);delete input.dataset.previewUrl;}if(!file){preview?.remove();label.classList.remove("has-image");if(copy)copy.querySelector("strong").textContent="Imagem da nação";return;}if(!preview){preview=document.createElement("img");preview.className="nation-image-preview";preview.dataset.nationImagePreview="";preview.alt="Prévia da imagem da nação";copy?.before(preview);}input.dataset.previewUrl=URL.createObjectURL(file);preview.src=input.dataset.previewUrl;label.classList.add("has-image");if(icon)icon.textContent="✓";if(copy)copy.querySelector("strong").textContent="Imagem selecionada";});
main.addEventListener("reset",event=>{if(event.target.id!=="community-request-form")return;const input=event.target.querySelector(".nation-image-upload input[type=file]");setTimeout(()=>{if(input?.dataset.previewUrl)URL.revokeObjectURL(input.dataset.previewUrl);if(input)delete input.dataset.previewUrl;event.target.querySelector("[data-nation-image-preview]")?.remove();const label=event.target.querySelector(".nation-image-upload");label?.classList.remove("has-image");const title=label?.querySelector(".nation-image-copy strong"),name=label?.querySelector("[data-nation-image-name]");if(title)title.textContent="Imagem da nação";if(name)name.textContent="PNG, JPG ou WebP · máximo 8 MB";},0);});






